class Solution {
public:
    int minRefuelStops(int target, int startFuel, vector<vector<int>>& stations) {
        priority_queue<int> pq;
        long long fuel = startFuel;
        int stops = 0;
        int prev = 0;
        int n = stations.size();
        for (int i = 0; i <= n; i++) {
            int pos = (i < n) ? stations[i][0] : target;
            int stationFuel = (i < n) ? stations[i][1] : 0;
            long long dist = pos - prev;
            while (fuel < dist && !pq.empty()) {
                fuel += pq.top();
                pq.pop();
                stops++;
            }
            if (fuel < dist) return -1;
            fuel -= dist;
            prev = pos;
            pq.push(stationFuel);
        }
        return stops;
    }
};
